def fill(self, coord, weight=1):
    """Fill histogram at *coord* with the given *weight*.

    Coordinates outside the histogram edges are ignored.
    """
    # Validate weight
    if not isinstance(weight, (int, float)):
        raise TypeError(f"weight must be a numeric scalar, got {type(weight).__name__}")
    # Ensure coord is iterable
    try:
        coord_iter = tuple(coord)
    except TypeError:
        coord_iter = (coord,)
    # Check dimensionality
    if len(coord_iter) != len(self.edges):
        raise ValueError(f"coord must have {len(self.edges)} dimensions, got {len(coord_iter)}")
    # Find bin indices
    indices = []
    for c, edges in zip(coord_iter, self.edges):
        # edges must be array-like
        if c < edges[0] or c >= edges[-1]:
            # Outside histogram bounds; ignore
            return
        # Find bin index
        idx = np.searchsorted(edges, c, side='right') - 1
        indices.append(idx)
    # Increment bin count
    try:
        self.bins[tuple(indices)] += weight
    except Exception as exc:
        raise RuntimeError(f"Failed to increment histogram bin: {exc}") from exc

def generate_default_observer_schema(app):
    """Generate the default observer schema for each Kubernetes resource present in
    ``spec.manifest`` for which a custom observer schema hasn't been specified.

    Args:
        app (krake.data.kubernetes.Application): The application for which to generate a
            default observer schema

    Returns:
        dict: A mapping from resource kind to its default observer schema.
    """
    # Basic validation of the input
    if app is None:
        raise ValueError("The 'app' argument must not be None.")
    if not hasattr(app, "spec"):
        raise AttributeError("The 'app' object must have a 'spec' attribute.")
    spec = app.spec

    # The manifest should be a list of resource dictionaries
    manifest = getattr(spec, "manifest", None)
    if manifest is None:
        raise AttributeError("The 'app.spec' object must have a 'manifest' attribute.")
    if not isinstance(manifest, list):
        raise TypeError("The 'app.spec.manifest' attribute must be a list of resources.")

    # Existing custom observer schemas, if any
    custom_schemas = getattr(spec, "observer_schema", {})
    if custom_schemas is None:
        custom_schemas = {}
    if not isinstance(custom_schemas, dict):
        raise TypeError("The 'app.spec.observer_schema' attribute must be a dict if present.")

    default_schemas = {}

    for resource in manifest:
        if not isinstance(resource, dict):
            # Skip non-dict entries
            continue
        kind = resource.get("kind")
        if not kind:
            # Skip resources without a kind
            continue

        # Skip if a custom schema is already defined for this kind
        if kind in custom_schemas:
            continue

        # Build a simple default schema: observe metadata and status
        # If the resource contains a status field, include it; otherwise, provide an empty dict
        status = resource.get("status", {})
        default_schema = {
            "metadata": {
                "name": "",
                "namespace": ""
            },
            "status": status
        }

        # Store the default schema for this kind
        default_schemas[kind] = default_schema

    return default_schemas

